import { Request, Response } from "express";
import puppeteer from "puppeteer-core";

// ── Types ─────────────────────────────────────────────────────────────────────
interface Unit {
  id: string;
  unitNumber: string;
  floor: string;
  area: string;
  unitType: string;
  description: string;
  features: string;
  pricePerMeter?: string;
  monthlyRent?: string;
  contractDuration?: string;
}

interface ProjectData {
  projectName: string;
  projectType: string;
  city: string;
  district: string;
  totalArea: string;
  floors: string;
  completionYear: string;
  description: string;
  amenities: string;
  contactName: string;
  features?: string;
  contactPhone: string;
  contactEmail: string;
  projectImage?: string;
  units: Unit[];
}

// ── Constants ─────────────────────────────────────────────────────────────────
const GOLD = "#C9A84C";
const DARK_BG = "#0F1117";
const DARK_PANEL = "#1A1F2E";
const LOGO = "data:image/png;base64,";

// ── Helpers ───────────────────────────────────────────────────────────────────
function kpiBar(kpis: {v:string,l:string}[], bg: string, numColor: string, lblColor: string, border: string) {
  return kpis.map(k => `
    <div style="flex:1;background:${bg};border-radius:6px;padding:10px 6px;text-align:center;border-top:3px solid ${border}">
      <div style="font-size:20px;font-weight:900;color:${numColor};line-height:1">${k.v}</div>
      <div style="font-size:8px;color:${lblColor};margin-top:3px;font-weight:600">${k.l}</div>
    </div>`).join("");
}

function amenityTags(list: string[], bg: string, color: string, border: string) {
  return list.map(a => `<span style="background:${bg};border:1px solid ${border};color:${color};font-size:8.5px;padding:3px 9px;border-radius:20px;font-weight:600">${a}</span>`).join("");
}

function footer(page: string, bg: string, textColor: string, accentColor: string) {
  const terms = [
    "✓ عقد 5 سنوات",
    "✓ دفع ربع سنوي",
    "✓ ضمان بنكي",
    "✓ لا معسلات"
  ].map(t => `<span style="color:${accentColor};font-size:7.5px;font-weight:700">${t}</span>`).join("");
  return `
  <div style="height:7.4mm;background:${bg};display:flex;align-items:center;justify-content:space-between;padding:0 28px;flex-shrink:0;gap:12px">
    <span style="color:${textColor};font-size:8px;font-weight:700;opacity:0.7">${page}</span>
    <div style="display:flex;gap:16px;flex:1;justify-content:center">${terms}</div>
    <span style="color:${textColor};font-size:7.5px;opacity:0.6">delmoninvest.com | 011-2080129</span>
  </div>`;
}

function logoHeader(bg: string, borderColor: string, titleColor: string, subtitleColor: string, subtitle: string) {
  return `
  <div style="height:14.8mm;background:${bg};border-bottom:2px solid ${borderColor};display:flex;align-items:center;justify-content:space-between;padding:0 28px;flex-shrink:0">
    <div style="display:flex;align-items:center;gap:10px">
      <img src="${LOGO}" style="height:36px;width:auto">
      <div>
        <div style="font-size:12px;font-weight:900;color:${titleColor};line-height:1.2">شركة دلمون للاستثمار</div>
        <div style="font-size:8px;color:${subtitleColor};letter-spacing:0.5px">DELMON INVESTMENT CO</div>
      </div>
    </div>
    <div style="text-align:left">
      <div style="font-size:8px;color:${subtitleColor};letter-spacing:1.5px;text-transform:uppercase">LEASING BROCHURE | بروشور التأجير</div>
      <div style="font-size:9px;font-weight:700;color:${titleColor};margin-top:2px">${subtitle}</div>
    </div>
  </div>`;
}

// ── Page 1 — Classic ──────────────────────────────────────────────────────────
function classicPage1(data: ProjectData, amenitiesList: string[], kpis: {v:string,l:string}[], imgSrc: string) {
  const imgBlock = imgSrc
    ? `<img src="${imgSrc}" style="width:100%;height:100%;object-fit:cover">`
    : `<div style="width:100%;height:100%;background:#e8e7e3;display:flex;align-items:center;justify-content:center;color:#aaa;font-size:40px">🏢</div>`;

  return `
  <div class="page">
    ${logoHeader("#fff", GOLD, "#2d2d2d", "#999", data.projectName)}
    <!-- Body: table layout for reliable height fill -->
    <table style="width:1123px;height:682px;border-collapse:collapse;table-layout:fixed">
      <tr>
        <!-- Image half: 48% = 539px -->
        <td style="width:539px;padding:0;overflow:hidden;position:relative;vertical-align:top">
          <div style="width:539px;height:682px;overflow:hidden;position:relative">
            ${imgBlock}
            <div style="position:absolute;bottom:0;left:0;right:0;height:100px;background:linear-gradient(transparent,rgba(0,0,0,0.8))"></div>
            <div style="position:absolute;bottom:14px;right:14px;left:14px;display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end">
              ${amenityTags(amenitiesList.slice(0,6), "rgba(201,168,76,0.9)", "#fff", "transparent")}
            </div>
          </div>
        </td>
        <!-- Content half -->
        <td style="vertical-align:top;padding:22px 28px 14px;background:#fff">
          <!-- Badge -->
          <div style="display:flex;justify-content:flex-end;margin-bottom:10px">
            <div style="background:${GOLD};color:#fff;font-size:8px;font-weight:800;padding:4px 14px;border-radius:2px;letter-spacing:0.5px">◆ وحدات شاغرة للتأجير</div>
          </div>
          <!-- Title -->
          <div style="text-align:right;margin-bottom:12px">
            <h1 style="font-size:44px;font-weight:900;color:#1a1a1a;line-height:1;margin:0 0 4px">${data.projectName}</h1>
            <div style="font-size:14px;font-weight:700;color:${GOLD};margin-bottom:4px">${data.projectType}</div>
            <div style="font-size:10px;color:#666">📍 ${data.city} — ${data.district}</div>
          </div>
          <!-- Description -->
          <div style="background:#F7F6F2;border-radius:6px;padding:12px 16px;border-right:4px solid ${GOLD};font-size:10px;color:#555;line-height:1.8;text-align:right;margin-bottom:14px">${data.description}</div>
          <!-- Amenities -->
          <div style="margin-bottom:14px">
            <div style="font-size:9px;font-weight:800;color:#2d2d2d;margin-bottom:8px;text-align:right;display:flex;align-items:center;justify-content:flex-end;gap:8px">
              <span>أبرز المرافق والخدمات</span>
              <div style="width:30px;height:2px;background:${GOLD}"></div>
            </div>
            <div style="display:flex;flex-wrap:wrap;gap:5px;justify-content:flex-end">
              ${amenityTags(amenitiesList, "#FBF9F3", "#6B5B2E", GOLD)}
            </div>
          </div>
          <!-- KPIs -->
          <div style="display:flex;gap:6px;margin-bottom:10px">
            ${kpiBar(kpis, "#F7F6F2", GOLD, "#888", GOLD)}
          </div>
          <!-- Features highlight -->
          ${data.features ? `
          <div>
            <div style="font-size:9px;font-weight:800;color:#2d2d2d;margin-bottom:6px;text-align:right;display:flex;align-items:center;justify-content:flex-end;gap:8px">
              <span>مميزات المشروع</span>
              <div style="width:30px;height:2px;background:${GOLD}"></div>
            </div>
            <div style="display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end">
              ${(data.features.split(",").filter(Boolean)).map((f: string) => `<span style="background:#F7F6F2;border:1px solid ${GOLD};color:#555;font-size:8px;padding:3px 10px;border-radius:3px">✓ ${f.trim()}</span>`).join("")}
            </div>
          </div>` : ""}
        </td>
      </tr>
    </table>
    ${footer("01 / 04", GOLD, "#fff", "rgba(255,255,255,0.9)")}
  </div>`;
}

