// ── Main builder ──────────────────────────────────────────────────────────────
function buildBrochureHTML(data: ProjectData, template: string): string {
  const amenitiesList = data.amenities
    ? data.amenities.split(/[,،\n]/).map((s: string) => s.trim()).filter(Boolean)
    : [];

  const imgSrc = data.projectImage ?? "";

  const kpis = [
    { v: data.totalArea ? Number(data.totalArea).toLocaleString("ar-SA") : "—", l: "المساحة م²" },
    { v: data.floors || "—", l: "الطوابق" },
    { v: data.units?.length ? String(data.units.length) : "—", l: "الوحدات" },
    { v: data.completionYear || "—", l: "الإنجاز" },
  ];

  let p1: string;
  if (template === "dark") p1 = darkPage1(data, amenitiesList, kpis, imgSrc);
  else if (template === "magazine") p1 = magazinePage1(data, amenitiesList, kpis, imgSrc);
  else p1 = classicPage1(data, amenitiesList, kpis, imgSrc);

  const p2 = page2(data, template, amenitiesList);
  const p3 = page3(data, template);
  const p4 = page4(data, template);

  return `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap" rel="stylesheet">
<style>
@page { size: 1123px 794px; margin: 0; }
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Cairo', sans-serif; direction: rtl; }
.page {
  width: 1123px;
  height: 794px;
  min-height: 794px;
  max-height: 794px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  page-break-after: always;
  break-after: page;
  position: relative;
}
.page-body {
  width: 1123px;
  height: 652px;
  display: flex;
  overflow: hidden;
  flex-shrink: 0;
}
.page-body-mag {
  width: 1123px;
  height: 618px;
  display: flex;
  overflow: hidden;
  flex-shrink: 0;
}
</style>
</head>
<body>
${p1}
${p2}
${p3}
${p4}
</body>
</html>`;
}

// ── Express route handler ─────────────────────────────────────────────────────
export async function pdfRouteHandler(req: Request, res: Response) {
  try {
    const { data, template = "classic" } = req.body as {
      data: ProjectData;
      template: string;
    };

    if (!data) {
      res.status(400).json({ error: "Missing data" });
      return;
    }

    const html = buildBrochureHTML(data, template);

    const browser = await puppeteer.launch({
      executablePath: "/usr/bin/chromium",
      headless: true,
      args: [
        "--no-sandbox",
        "--disable-setuid-sandbox",
        "--disable-dev-shm-usage",
        "--disable-gpu",
        "--font-render-hinting=none",
      ],
    });

    const page = await browser.newPage();
    await page.setViewport({ width: 1123, height: 794, deviceScaleFactor: 1 });
    await page.emulateMediaType("screen");
    await page.setContent(html, {
      waitUntil: ["load", "domcontentloaded"],
      timeout: 30000,
    });

    await page.evaluate(() => (document as any).fonts.ready);
    await new Promise((r) => setTimeout(r, 2000));

    const pdfBuffer = await page.pdf({
      width: "297mm",
      height: "210mm",
      preferCSSPageSize: true,
      printBackground: true,
      margin: { top: "0", right: "0", bottom: "0", left: "0" },
    });

    await browser.close();

    const projectName = data.projectName || "بروشور-دلمون";
    const city = data.city ? `-${data.city}` : "";
    const date = new Date().toISOString().split("T")[0];
    const filename = encodeURIComponent(`بروشور-دلمون-${projectName}${city}-${date}.pdf`);

    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename*=UTF-8\'\'${filename}`);
    const buf = Buffer.isBuffer(pdfBuffer) ? pdfBuffer : Buffer.from(pdfBuffer);
    res.setHeader("Content-Length", buf.length);
    res.end(buf);
  } catch (err) {
    console.error("[PDF Route Error]", err);
    res.status(500).json({ error: "فشل توليد PDF", details: String(err) });
  }
}
